package com.bombay.restaurantintelligence.web;
import com.bombay.restaurantintelligence.whatsapp.*; import java.util.Map; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController public class WhatsAppWebhookController {private final String verifyToken;private final WhatsAppWebhookService service;private final WhatsAppSignatureVerifier signatures;public WhatsAppWebhookController(@Value("${app.whatsapp.verify-token}")String verifyToken,WhatsAppWebhookService service,WhatsAppSignatureVerifier signatures){this.verifyToken=verifyToken;this.service=service;this.signatures=signatures;}@GetMapping("/api/whatsapp/webhook") public ResponseEntity<String> verify(@RequestParam(name="hub.mode",required=false)String mode,@RequestParam(name="hub.verify_token",required=false)String token,@RequestParam(name="hub.challenge",required=false)String challenge){if("subscribe".equals(mode)&&verifyToken.equals(token))return ResponseEntity.ok(challenge);return ResponseEntity.status(HttpStatus.FORBIDDEN).body("verification failed");}@PostMapping(value="/api/whatsapp/webhook",consumes=MediaType.APPLICATION_JSON_VALUE)public ResponseEntity<Map<String,Object>> inbound(@RequestBody String body,@RequestHeader(name="X-Hub-Signature-256",required=false)String signature){if(!signatures.valid(body,signature))return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("accepted",false));return ResponseEntity.ok(Map.of("accepted",true,"processed",service.process(body)));}}
